std::mutex m;

// 1. std::defer_lock_t: Do not lock now
// L1 created, mutex m is not locked.
std::unique_lock<std::mutex> L1(m, std::defer_lock);
L1.lock(); // Manual acquisition

// 2. std::try_to_lock_t: Non-blocking attempt
std::unique_lock<std::mutex> L2(m, std::try_to_lock);
if (L2.owns_lock()) { /* critical section */ }

// 3. std::adopt_lock_t: Assume lock is already held
m.lock();
// L3 takes ownership of the existing lock on m
std::unique_lock<std::mutex> L3(m, std::adopt_lock);

